import itertools

def reduce(instance):
    """Reduce Vertex Cover instance to SAT instance.
    instance: dict with keys 'n', 'edges', 'k'
    Returns dict with keys 'num_vars', 'clauses' as per SAT definition.
    """
    n = instance.get('n')
    edges = instance.get('edges', [])
    k = instance.get('k')

    # Edge cases
    if k < 0:
        # Unsatisfiable formula: a single empty clause
        return {"num_vars": 1, "clauses": [[]]}
    if k == 0:
        if not edges:
            # trivially satisfiable (no constraints)
            return {"num_vars": 1, "clauses": []}
        else:
            return {"num_vars": 1, "clauses": [[]]}
    if k >= n:
        # Always yes, return trivially satisfiable formula
        return {"num_vars": 1, "clauses": []}

    # General case: use variables x_{i,j} meaning vertex i occupies position j (0-indexed)
    num_vars = n * k
    def var(i, j):
        # i in [0,n-1], j in [0,k-1]
        return i * k + j + 1  # SAT variables are 1-indexed

    clauses = []

    # 1. Each position j must be occupied by at least one vertex
    for j in range(k):
        clause = [var(i, j) for i in range(n)]
        clauses.append(clause)

    # 2. No vertex appears in two different positions (at most once)
    for i in range(n):
        for j in range(k):
            for l in range(j + 1, k):
                clauses.append([-var(i, j), -var(i, l)])

    # 3. No position is occupied by two different vertices (at most one)
    for j in range(k):
        for i in range(n):
            for l in range(i + 1, n):
                clauses.append([-var(i, j), -var(l, j)])

    # 4. Edge covering: for each edge (u,v) at least one endpoint is selected in some position
    for (u, v) in edges:
        clause = []
        for j in range(k):
            clause.append(var(u, j))
            clause.append(var(v, j))
        clauses.append(clause)

    return {"num_vars": num_vars, "clauses": clauses}

